INSERT INTO `achievement_locale` VALUES (13452,'deDE','','Schrecklicher Sattel (1)','',69497),(13452,'esES','','Silla de montar sañosa (1)','',69497),(13452,'esMX','','Silla de montar sañosa (1)','',69497),(13452,'frFR','','Selle vicieuse (1)','',69497),(13452,'itIT','','Sella Malvagia (1)','',69497),(13452,'koKR','','흉포한 안장 (1)','',69497),(13452,'ptBR','','Sela Cruel (1)','',69497),(13452,'ruRU','','Седло ярости (1)','',69497),(13452,'zhCN','','邪气鞍座（1）','',69497),(13452,'zhTW','','凶惡鞍具（1）','',69497),(13453,'deDE','','Schrecklicher Sattel (1)','',69497),(13453,'esES','','Silla de montar sañosa (1)','',69497),(13453,'esMX','','Silla de montar sañosa (1)','',69497),(13453,'frFR','','Selle vicieuse (1)','',69497),(13453,'itIT','','Sella Malvagia (1)','',69497),(13453,'koKR','','흉포한 안장 (1)','',69497),(13453,'ptBR','','Sela Cruel (1)','',69497),(13453,'ruRU','','Седло ярости (1)','',69497),(13453,'zhCN','','邪气鞍座（1）','',69497),(13453,'zhTW','','凶惡鞍具（1）','',69497),(16110,'deDE','Erfahrt von Gwybod fünf Fakten über Hyänen bei einem einzigen Besuch in der Brackenfellhöhle auf dem Schwierigkeitsgrad \'Mythisch\'.','Alles, was man über Hyänen wissen muss','',69497),(16110,'esES','Descubre cinco datos sobre las hienas de Gwybod en una sola visita a la Hondonada Frondacuero en dificultad mítica.','Te has suscrito a los datos de las hienas','',69497),(16110,'esMX','Aprende cinco curiosidades de las hienas de Gwybod en una misma visita a Hondonada Frondacuero en dificultad mítica.','Suscripción a Curiosidades de hienas','',69497),(16110,'frFR','Apprendre 5 anecdotes sur les hyènes auprès de Gwybod en une seule visite au creux des Fougerobes en mode mythique.','Tout savoir sur les hyènes','',69497),(16110,'itIT','Apprendi cinque Fatti sulle iene da Gwybod in una singola visita alla Conca dei Felcepelle in modalità Mitica.','Abbonamento ai Fatti sulle iene','',69497),(16110,'koKR','신화 난이도에서 한 번의 담쟁이가죽 골짜기 방문으로 귀보드에게서 하이에나에 관한 다섯 가지 사실 배우기','하이에나의 진실에 온 아제로스가 경악한 사연','',69497),(16110,'ptBR','Aprender cinco fatos sobre hienas com Gwybod em uma única visita à Clareira de Courambaia, no modo Mítico.','Assinou as Curiosidades das Hienas','',69497),(16110,'ruRU','Узнайте пять фактов о гиенах от Гвайбода за один поход в лощину Бурошкуров в эпохальном режиме.','Подписка на \"Факты о гиенах\"','',69497),(16110,'zhCN','在史诗难度下的单次蕨皮山谷之旅中，从古威波德那里了解五点关于土狼的知识。','锁定土狼频道','',69497),(16110,'zhTW','在傳奇難度的蕨皮谷，於一次行動中從圭寶那裡獲得5個土狼知識。','土狼知識家','',69497),(16281,'deDE','Besiegt Chronolord Deios in Uldaman: Vermächtnis von Tyr auf dem Schwierigkeitsgrad \'Mythisch\', nachdem Ihr 20 fallende Ewigkeitskugeln vor dem Aufprall auf den Boden aufgefangen habt.','Wie Sand im Stundenglas','',69497),(16281,'esES','Derrota al cronolord Deios tras atrapar 20 orbes de eternidad mientras caen al suelo en Uldaman: Legado de Tyr en dificultad mítica.','Como arena en un reloj','',69497),(16281,'esMX','Derrota al cronolord Deios después de capturar 20 orbes de eternidad cuando caen al piso en Uldaman: Legado de Tyr en dificultad mítica.','Las arenas del tiempo','',69497),(16281,'frFR','Vaincre le chronoseigneur Déios en ayant attrapé 20 orbes d’éternité qui tombent dans Uldaman : l’héritage de Tyr en mode mythique.','Comme les grains dans un sablier','',69497),(16281,'itIT','Sconfiggi il Cronosignore Deios dopo aver afferrato 20 Globi dell\'Eternità mentre cadono a terra in Uldaman: Eredità di Tyr in modalità Mitica.','Come la sabbia nella clessidra','',69497),(16281,'koKR','울다만: 티르의 유산에서 지면에 떨어지는 영원의 보주 20개를 받아낸 후 시간의 군주 데이오스 처치 (신화)','모래시계 속 흐르는 모래처럼','',69497),(16281,'ptBR','Derrotar o Crono-lorde Deios depois de pegar 20 Orbes da Eternidade à medida que eles caírem no chão em Uldaman: Legado de Tyr, no modo Mítico.','Como areia na ampulheta','',69497),(16281,'ruRU','Победите хронолорда Дейоса, поймав 20 падающих вечных сфер в подземелье \"Ульдаман: наследие Тира\" в эпохальном режиме.','Как песок в часах','',69497),(16281,'zhCN','在20个永恒宝珠落到地面时接住它们，然后击败奥达曼：提尔的遗产的时空领主戴欧斯（史诗难度）。','流沙过隙','',69497),(16281,'zhTW','在傳奇難度的奧達曼：提爾的遺產，捕捉20顆往地面墜落的永恆之球後，擊敗時空領主戴歐司。','沙漏裡的流沙','',69497),(16282,'deDE','Besiegt Schildwache Kralldras in Uldaman: Vermächtnis von Tyr auf dem Schwierigkeitsgrad \'Mythisch\', nachdem Ihr Schildwache Kralldras und alle Gruppenmitglieder gleichzeitigt betäubt habt.','Nein, seid Ihr umwerfend!','',69497),(16282,'esES','Derrota a la centinela Talondras tras aturdirlo al mismo tiempo que a todos los miembros del grupo en Uldaman: Legado de Tyr en dificultad mítica.','¡Atúrdeme esto!','',69497),(16282,'esMX','Derrota a la centinela Talondras después de aturdir al mismo tiempo a la centinela Talondras y a todos los miembros del grupo en Uldaman: Legado de Tyr en dificultad mítica.','Me aturdes','',69497),(16282,'frFR','Vaincre la sentinelle Talondras en ayant étourdi simultanément Talondras et tous les membres du groupe dans Uldaman : l’héritage de Tyr en mode mythique.','Quelle beauté étourdissante !','',69497),(16282,'itIT','Sconfiggi la Sentinella Talondras dopo aver stordito contemporaneamente la Sentinella Talondras e tutti i membri del gruppo in Uldaman: Eredità di Tyr in modalità Mitica.','No! Stai stordendo!','',69497),(16282,'koKR','울다만: 티르의 유산에서 파수꾼 탈론드라스와 모든 파티원을 동시에 기절시킨 후 파수꾼 탈론드라스 처치 (신화)','기절초풍','',69497),(16282,'ptBR','Derrotar o Sentinela Garrandras logo depois de atordoar o sentinela e todos os integrantes do grupo em Uldaman: Legado de Tyr no modo Mítico.','Não, a sua beleza é de atordoar!','',69497),(16282,'ruRU','Победите часовую Талондрас, одновременно оглушив ее и всех участников группы в подземелье \"Ульдаман: наследие Тира\" в эпохальном режиме.','Взаимное ошеломление','',69497),(16282,'zhCN','在哨兵塔隆达丝和所有小队成员都同时昏迷后，击败奥达曼：提尔的遗产的哨兵塔隆达丝（史诗难度）。','不，你才晕菜了！','',69497),(16282,'zhTW','在傳奇難度的奧達曼：提爾的遺產，同時擊昏哨兵泰龍爪斯和所有隊伍成員後，擊敗哨兵泰龍爪斯。','昏昏沉沉','',69497),(16296,'deDE','Besiegt Hackklaues Kriegsmeute in der Brackenfellhöhle auf dem Schwierigkeitsgrad \'Mythisch\', nachdem Ihr Häuptling Sanftpfote befreit, mit Speer und Schild ausgestattet und sichergestellt habt, dass sie überlebt.','Knurrbossifizierung','',69497),(16296,'esES','Derrota a la banda guerrera de Cortagarra tras liberar a la jefa Zarpasuave, equiparla con una lanza y un escudo, y asegurarte de que sobrevive al combate en la Hondonada Frondacuero en dificultad mítica.','Gruñijefemiento','',69497),(16296,'esMX','Libera a la jefa Patasuave, equípale una lanza y un escudo, logra que sobreviva y luego derrota a la Banda de guerra de Hachagarra en Hondonada Frondacuero en dificultad mítica.','La jefa ante todo','',69497),(16296,'frFR','Vaincre le bataillon de Griffentaille après avoir libéré la cheffe Patte Douce, l’avoir équipée d’une lance et d’un bouclier, et avoir fait en sorte qu’elle survive dans le creux des Fougerobes en mode mythique.','GRRR !','',69497),(16296,'itIT','Sconfiggi la Banda di Graffiartigli dopo aver liberato la Capa Zampamolle, equipaggiandola con una lancia e uno scudo, e assicurandoti che sopravviva nella Conca dei Felcepelle in modalità Mitica.','Complice di fuga','',69497),(16296,'koKR','담쟁이가죽 골짜기에서 족장 소프트포우를 구출한 후, 창과 방패를 장착시킨 다음 죽지 않게 살피면서 헤클로의 전투단 처치 (신화)','의기양양한 포효','',69497),(16296,'ptBR','Derrotar o Grupo de Guerra de Talhagarra após fugir da Chefe Patafofa, equipando-a com uma lança e um escudo e assegurando que ela sobreviva na Clareira de Courambaia no modo Mítico.','Rosnado do Chefe','',69497),(16296,'ruRU','Освободите вождя Мягкую Лапу, вооружите ее копьем и щитом, доведите ее живой до конца подземелья, а затем победите боевой отряд Когтерезки в лощине Бурошкуров в эпохальном режиме.','Собачья работа','',69497),(16296,'zhCN','在蕨皮山谷解救柔爪酋长，用矛和盾武装她，并确保她活下来，然后击败劈爪的战团（史诗难度）。','盛气凌人','',69497),(16296,'zhTW','在傳奇難度的蕨皮谷，於釋放柔掌酋長、為她裝備長矛與盾牌，並確保她安然存活後，擊敗砍爪戰隊。','咆嘯示威','',69497),(16320,'deDE','Besiegt Kokia Feuerhuf in den Rubinlebensbecken auf dem Schwierigkeitsgrad \'Mythisch\', nachdem Ihr vier Lebensbecken mit \'Geschmolzener Brocken\' erhitzt habt.','Verursacht Dampf Feuerschaden?','',69497),(16320,'esES','Derrota a Kokia Pezuña de Fuego tras calentar 4 estanques de vida con roca fundida en los Estanques de Vida Rubí en dificultad mítica.','¿El vapor quema?','',69497),(16320,'esMX','Derrota a Kokia Pezuña Ardiente después de calentar cuatro estanques de vida con Roca fundida en los Estanques de Vida Rubí en dificultad mítica.','¿El vapor inflige daño de fuego?','',69497),(16320,'frFR','Terrasser Kokia Foulebraise après avoir chauffé 4 bassins de l’Essence avec un rocher en fusion dans les bassins de l’Essence rubis en mode mythique.','Ça brûle, la vapeur ?','',69497),(16320,'itIT','Sconfiggi Kokia Zoccolo Ardente dopo aver scaldato 4 pozze della vita con Macigno Fuso nelle Pozze della Vita di Rubino in modalità Mitica.','Il vapore infligge danni da fuoco?','',69497),(16320,'koKR','루비 생명의 웅덩이에서 타오르는 바위로 생명의 웅덩이 4개를 가열한 후 코키아 블레이즈후프 처치 (신화)','증기도 화염 피해 주나요?','',69497),(16320,'ptBR','Derrotar Kokia Patardida depois de aquecer 4 poços de vida com Pedregulho Derretido nos Poços da Vida Rubi, no modo Mítico.','Vapor causa dano de Fogo?','',69497),(16320,'ruRU','Победите Кокию Пламенное Копыто в Рубиновых Омутах Жизни в эпохальном режиме после того, как разогреете 4 омута с помощью пылающего валуна.','Наносит ли пар урон от огня?','',69497),(16320,'zhCN','用熔火巨石给4个新生法池加热后，击败红玉新生法池的柯姬雅·焰蹄（史诗难度）。','蒸汽会造成火焰伤害吗？','',69497),(16320,'zhTW','在傳奇難度的晶紅生命之池，用熔岩巨石加熱4座生命之池後，擊敗可幾亞‧焰蹄。','蒸汽會造成火焰傷害嗎？','',69497),(16330,'deDE','Besiegt Umbrelskul im Azurblauen Gewölbe auf dem Schwierigkeitsgrad \'Mythisch\', ohne von einer polymorphen Falle getroffen zu werden oder \'Schriller Schrei\' auszulösen.','Eine ehrliche Haut','',69497),(16330,'esES','Derrota a Umbracráneo sin que te alcance una trampa de polimorfia ni activar Graznido en la Cámara Azur en dificultad mítica.','Te queda pellejo','',69497),(16330,'esMX','Derrota a Umbrelskul sin recibir un golpe de una trampa de polimorfia ni activar Chillido en la Bóveda Azur en dificultad mítica.','Debes estar hecho de cuero','',69497),(16330,'frFR','Vaincre Krânombrel sans se faire toucher par un piège de métamorphose ni déclencher de Cri perçant dans le caveau d’Azur en mode mythique.','À fleur de peau','',69497),(16330,'itIT','Sconfiggi Umbrelskul senza far scattare una trappola polimorfica o un Grido nella Cripta Azzurra in modalità Mitica o Mitica+.','Bisogna avere una pellaccia','',69497),(16330,'koKR','하늘빛 보관소에서 변이 덫에 적중당하거나 울음을 발동시키지 않고 엄브렐스컬 처치 (신화)','회피의 달인','',69497),(16330,'ptBR','Derrotar Umbracrânio sem ser atingido por uma armadilha de polimorfia ou acionar um Guincho na Câmara Lazúli, no modo Mítico.','Você É Feito de Couro?','',69497),(16330,'ruRU','Победите Мраскула в Лазурном хранилище в эпохальном режиме, не активируя превращающую ловушку или способность \"Визг\".','Рожденные прятаться','',69497),(16330,'zhCN','没被变形术陷阱击中，也没触发尖鸣的情况下，击败碧蓝魔馆的安布雷斯库（史诗难度）。','躲避大师','',69497),(16330,'zhTW','在傳奇難度的蒼藍密庫，在不被變形術陷阱命中或觸發尖叫的情況下，擊敗安珀斯庫。','天生我藏必有用','',69497),(16331,'deDE','Besiegt Umbrelskul im Azurblauen Gewölbe auf dem Schwierigkeitsgrad \'Mythisch\', nachdem Ihr schimmernde Geoden mit \'Drachenstoß\' zertrümmert und neun Geodenstücke zerstört habt.','Der gesprungene Kristall','',69497),(16331,'esES','Derrota a Umbracráneo tras aplastar geodas fulgurantes con Golpe de dragón y destruir nueve trozos de geoda en la Cámara Azur en dificultad mítica.','El cristal agrietado','',69497),(16331,'esMX','Derrota a Umbrelskul después de destrozar geodas fulgurantes con Golpe dragón y destruir 9 trozos de geodas en La Bóveda Azur en dificultad mítica.','El cristal agrietado','',69497),(16331,'frFR','Vaincre Krânombrel après avoir éclaté des géodes chatoyantes avec la Frappe draconique et détruit 9 fragments de géode dans le caveau d’Azur en mode mythique.','Le cristal fêlé','',69497),(16331,'itIT','Sconfiggi Umbrelskul dopo aver distrutto i Geodi Scintillanti con Assalto del Drago e 9 Pezzi di Geode nella Cripta Azzurra in modalità Mitica.','Una crepa nel cristallo','',69497),(16331,'koKR','하늘빛 보관소에서 용의 강타로 일렁이는 정동석을 깨뜨리고 정동석 덩어리 9개를 파괴한 후 엄브렐스컬 처치 (신화)','금이 간 수정','',69497),(16331,'ptBR','Derrotar Umbracrânio após esmagar Geodos Cintilantes com Golpe do Dragão e destruir os 9 Pedaços de Geodo na Câmara Lazúli, no modo Mítico.','Cristal Estilhaçado','',69497),(16331,'ruRU','Разбейте мерцающие жеоды \"Ударом дракона\" и уничтожьте 9 крупных жеод, а затем победите Мраскула в Лазурном хранилище в эпохальном режиме.','Треснувший кристалл','',69497),(16331,'zhCN','用巨龙打击猛击闪光的晶簇，并摧毁九个晶簇块之后，击败碧蓝魔馆的安布雷斯库（史诗难度）。','开裂水晶','',69497),(16331,'zhTW','在傳奇難度的蒼藍密庫，以龍擊粉碎幻光晶簇與摧毀9個晶簇塊後，擊敗安珀斯庫。','破裂水晶','',69497),(16337,'deDE','Besiegt Bromach in Uldaman: Vermächtnis von Tyr auf dem Schwierigkeitsgrad \'Mythisch\', solange noch mindestens 10 Steingrufttroggs am Leben sind.','Trogg frisst Trogg frisst Trogg','',69497),(16337,'esES','Derrota a Bromach con 10 o más troggs Grutacanto todavía vivos en Uldaman: Legado de Tyr en dificultad mítica.','Trogg sí come trogg','',69497),(16337,'esMX','Derrota a Bromach mientras hay 10 troggs grutacanto o más con vida en Uldaman: Legado de Tyr en dificultad mítica.','La ley de la gruta','',69497),(16337,'frFR','Vaincre Bromach tant qu’il reste au moins 10 Troggs cavepierres en vie dans Uldaman : l’héritage de Tyr en mode mythique.','La loi du plus Trogg','',69497),(16337,'itIT','Sconfiggi Bromach mentre 10 o più Trogg della Volta sono ancora vivi a Uldaman: Eredità di Tyr, in modalità Mitica.','Trogg mangia Trogg','',69497),(16337,'koKR','울다만: 티르의 유산에서 바위동굴 트로그가 10마리 이상 살아있는 상태로 브로마크 처치 (신화)','어설픈 트로그는 살아남지 못한다','',69497),(16337,'ptBR','Derrotar Bromach enquanto 10 ou mais Troggs da Abóbada de Pedra ainda estiverem vivos em Uldaman: Legado de Tyr no modo Mítico.','É Trogg Comendo Mundo de Trogg','',69497),(16337,'ruRU','Победите Бромача, пока 10 или более троггов из племени Каменного Свода еще живо, в подземелье \"Ульдаман: наследие Тира\" в эпохальном режиме.','Трогг трогга не трогай','',69497),(16337,'zhCN','在有至少10个石窟穴居人存活的情况下击败奥达曼：提尔的遗产的布罗马奇（史诗难度）。','这是个穴居人渣的残酷世界','